using System;using System.Diagnostics;using System.Windows.Media.Media3D;
class UprightTest{
 static void Check(bool value,string why){if(!value)throw new Exception(why);}
 static Model3DGroup Cone(Vector3D axis){var mesh=new MeshGeometry3D();var across=Vector3D.CrossProduct(axis,new Vector3D(0,0,1));if(across.Length<.1)across=new Vector3D(1,0,0);across.Normalize();var other=Vector3D.CrossProduct(axis,across);for(int h=0;h<=100;h++)for(int j=0;j<40;j++){double a=j*Math.PI/20,r=1-h/100.0;var v=axis*(h*.1)+(across*Math.Cos(a)+other*Math.Sin(a))*r;mesh.Positions.Add(new Point3D(v.X,v.Y,v.Z));}var group=new Model3DGroup();group.Children.Add(new GeometryModel3D{Geometry=mesh});return group;}
 [STAThread]static int Main(){foreach(var axis in new[]{new Vector3D(1,0,0),new Vector3D(0,-1,0),new Vector3D(0,0,-1),new Vector3D(0,0,1)}){var group=Cone(axis);var watch=Stopwatch.StartNew();var matrix=ModelRender.AutoOrientation(group);var result=matrix.Transform(axis);Check(result.Z>.99,"Tapered shape did not stand upright");Check(group.Transform.Value.IsIdentity,"Source transform changed");Console.WriteLine("Taper "+axis+": PASS "+watch.Elapsed.TotalMilliseconds.ToString("F2")+"ms");}
 var transformed=Cone(new Vector3D(0,0,1));var original=Matrix3D.Identity;original.Rotate(new Quaternion(new Vector3D(0,1,0),90));original.Translate(new Vector3D(17,-9,6));transformed.Transform=new MatrixTransform3D(original);var correction=ModelRender.AutoOrientation(transformed);Check(correction.Transform(original.Transform(new Vector3D(0,0,1))).Z>.99,"Existing transform ignored");Check(transformed.Transform.Value==original,"Existing source transform changed");
 var assembly=Cone(new Vector3D(1,0,0));assembly.Children.Add(assembly.Children[0]);Check(ModelRender.AutoOrientation(assembly).IsIdentity,"Assembly was rearranged");
 var sphere=new MeshGeometry3D();for(int i=0;i<30;i++)for(int j=0;j<30;j++){double a=i*Math.PI/15,b=j*Math.PI/15;sphere.Positions.Add(new Point3D(Math.Sin(a)*Math.Cos(b),Math.Sin(a)*Math.Sin(b),Math.Cos(a)));}var round=new Model3DGroup();round.Children.Add(new GeometryModel3D{Geometry=sphere});Check(ModelRender.AutoOrientation(round).IsIdentity,"Round shape guessed incorrectly");Console.WriteLine("Round and multi-part fallback: PASS");return 0;}
}